<script lang="ts">
 import {SkeletonLoader,SpinnerLoader} from '$lib/components/loaders';
 import {api} from './api';
 import {untrack} from 'svelte';
 import {enter} from './motion';
 let {company,onupdated}:{company:string;onupdated:()=>void}=$props();
 let data:any=$state(null),form:any=$state(null),holidays=$state(''),busy=$state(false),error=$state(''),notice=$state('');
 const days=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
 let generation=0,loading=$state(true);
 const lineName=(value:string)=>value==='General'?'Non-production (legacy)':value;
 async function load(){const n=++generation;loading=true;try{const value=await api('/sample-capacities');if(n===generation)data=value}catch(e){if(n===generation)error=(e as Error).message}finally{if(n===generation)loading=false}}
 $effect(()=>{company;untrack(()=>{form=null;data=null;notice='';error='';load()})});
 function edit(record:any=null){error='';notice='';form=record?structuredClone($state.snapshot(record)):{company_id:Number(company),resource:'Line 1',capacity_mode:'Default',effective_date:new Date().toLocaleDateString('en-CA',{timeZone:'Asia/Kolkata'}),end_date:'',tailors:2,pieces_per_tailor:2,weekly_off:[0]};holidays=(record?.holidays||[]).join('\n')}
 async function save(e:SubmitEvent){e.preventDefault();if(busy)return;const scope=company;busy=true;error='';try{await api('/sample-capacities',{...form,holidays:holidays.split(/[\n,]/).map(s=>s.trim()).filter(Boolean)});if(company!==scope)return;form=null;await load();onupdated();notice='Capacity saved. Reserved plans keep their dates; new plans use these capacity rules.'}catch(e){if(company===scope)error=(e as Error).message}finally{busy=false}}
</script>
<section class="sample-capacity" aria-label="Non-production capacity">
 <header><div><h3>Non-production · Sample capacity</h3><p>Set each line’s daily allowance. On-demand capacity replaces the default only for its date range.</p></div>{#if data?.can_edit}<button class="button primary" disabled={!company||busy} onclick={()=>edit()}>Add capacity</button>{/if}</header>
 {#if !company}<p>Select a workspace company to configure capacity.</p>{/if}
 {#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if notice}<p class="capacity-notice" role="status">{notice}</p>{/if}
 {#if form}<form class="capacity-editor" onsubmit={save} use:enter>
  <div class="capacity-title"><h3>{form.id?'Edit':'Add'} sample capacity</h3><span>Non-production / Sample</span></div>
  <div class="capacity-fields">
   <label>Sample line<input list="sample-lines" required maxlength="80" bind:value={form.resource} readonly={!!form.id}/><datalist id="sample-lines"><option>Line 1</option><option>Line 2</option><option>Suit line 1</option></datalist></label>
   <label>Capacity type<select bind:value={form.capacity_mode}><option>Default</option><option>On demand</option></select></label>
   <label>From date<input type="date" required bind:value={form.effective_date} readonly={!!form.id}/></label>
   <label>To date {form.capacity_mode==='Default'?'(optional)':''}<input type="date" min={form.effective_date} required={form.capacity_mode==='On demand'} bind:value={form.end_date}/></label>
   <label>Sample tailors<input type="number" required min="0" max="500" step="1" bind:value={form.tailors}/></label>
   <label>Pieces per tailor / day<input type="number" required min="1" max="200" step="1" bind:value={form.pieces_per_tailor}/></label>
   <div class="capacity-total" aria-live="polite"><span>Daily capacity</span><strong>{(form.tailors||0)*(form.pieces_per_tailor||0)} pieces</strong><small>{form.tailors||0} tailors × {form.pieces_per_tailor||0} pieces</small></div>
  </div>
  <div class="capacity-calendar"><fieldset><legend>Weekly off</legend><div>{#each days as day,n}<label class="capacity-check"><input type="checkbox" checked={form.weekly_off.includes(n)} onchange={e=>form.weekly_off=e.currentTarget.checked?[...form.weekly_off,n]:form.weekly_off.filter((v:number)=>v!==n)}/>{day}</label>{/each}</div></fieldset><label>Holidays (YYYY-MM-DD, one per line)<textarea rows="2" bind:value={holidays}></textarea></label></div>
  <p class="capacity-help">{form.capacity_mode==='On demand'?'The default automatically resumes after the To date. Overlapping on-demand ranges are not allowed.':'The default starts on the From date. Leave To date blank to continue until a newer default starts.'} Zero tailors pauses the line. Reserved work cannot be overbooked by reducing capacity.</p>
  <footer><button type="button" class="button secondary" disabled={busy} onclick={()=>form=null}>Cancel</button><button class="button primary" disabled={busy}>{busy?'Saving…':'Save capacity'}</button></footer>
 </form>{/if}
 {#if loading&&data}<SpinnerLoader label="Updating capacity…"/>{/if}
 <div class="capacity-scroll" aria-busy={loading}><table><thead><tr><th>Sample line</th><th>Type</th><th>From → To</th><th>Tailors × pieces</th><th>Daily capacity</th><th>Weekly off</th><th>Holidays</th><th>Action</th></tr></thead><tbody>{#each (data?.records||[]).filter((r:any)=>String(r.company_id)===company) as r}<tr><td><strong>{lineName(r.resource)}</strong></td><td>{r.capacity_mode}</td><td>{r.effective_date}<small>to {r.end_date||'Ongoing'}</small></td><td>{r.tailors} × {r.pieces_per_tailor}</td><td><strong>{r.tailors*r.pieces_per_tailor} pcs</strong></td><td>{r.weekly_off.map((n:number)=>days[n]).join(', ')||'None'}</td><td>{r.holidays.join(', ')||'None'}</td><td>{#if data.can_edit}<button class="button secondary" disabled={busy} onclick={()=>edit(r)}>Edit</button>{/if}</td></tr>{:else}<tr><td colspan="8">{#if loading&&!data}<SkeletonLoader variant="table" rows={3} columns={7} label="Loading sample capacity…"/>{:else}No capacity configured. Super Admin can add the actual sample tailors and daily output for each line.{/if}</td></tr>{/each}</tbody></table></div>
</section>
<style>
 /* Scoped to sampling; the established global form and navigation styles remain. */
 .sample-capacity{color:#17212f}.sample-capacity>header{display:flex;justify-content:space-between;align-items:start;gap:16px;margin:16px 0}.sample-capacity h3{margin:0;font-size:16px;font-weight:700}.sample-capacity p{font-size:13px;line-height:1.5;margin:6px 0;color:#374151}.capacity-scroll{overflow:auto;border:1px solid #dce3e9;border-radius:16px}table{width:100%;min-width:940px;border-collapse:collapse;font-size:13px}th,td{padding:12px;text-align:left;border-bottom:1px solid #e5e9ee}th{background:#f6f8fa;color:#374151;font-size:12px}td{color:#17212f}small{display:block;color:#374151;font-size:12px;margin-top:3px}.capacity-editor{border:1px solid #ccd8e1;border-radius:16px;overflow:hidden;background:#fff;margin:16px 0}.capacity-title{display:flex;justify-content:space-between;align-items:center;padding:12px 16px;background:#162d40;color:#fff}.sample-capacity .capacity-editor .capacity-title h3,.capacity-title span{color:#fff!important;-webkit-text-fill-color:#fff}.capacity-title span{font-size:12px}.capacity-fields{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:16px}.capacity-editor label{display:grid;gap:6px;color:#17212f;font-size:13px;font-weight:600;min-width:0}.capacity-editor :is(input:not([type=checkbox]),select,textarea){width:100%;min-width:0;min-height:44px;border:1px solid #c8d3dd;border-radius:10px;background:#f6f8fa;padding:9px 10px;font:inherit;color:#111}.capacity-total{grid-column:span 2;display:flex;align-items:center;gap:12px;border:1px solid #bddfd6;background:#effaf6;border-radius:12px;padding:12px;color:#075c51}.capacity-total strong{font-size:20px;color:#075c51}.capacity-total small{color:#185f53;margin:0}.capacity-calendar{display:grid;grid-template-columns:2fr 1fr;gap:16px;padding:0 16px}.capacity-calendar fieldset{min-width:0;border:1px solid #dce3e9;border-radius:10px;padding:6px 12px}.capacity-calendar legend{font-size:13px;font-weight:600}.capacity-calendar fieldset>div{display:flex;flex-wrap:wrap;gap:0 12px}.capacity-editor .capacity-check{display:flex;align-items:center;gap:7px;min-height:44px;font-size:12px}.capacity-check input{width:18px;height:18px;accent-color:#08776e}.capacity-editor .capacity-help{padding:12px 16px;margin:0}.capacity-editor footer{display:flex;justify-content:flex-end;gap:8px;border-top:1px solid #dce3e9;padding:12px 16px}.sample-capacity :is(input,select,textarea,button):focus-visible{outline:3px solid #08776e;outline-offset:2px}.sample-capacity .capacity-notice{background:#effaf6;color:#075c51;padding:12px;border-radius:10px}@media(max-width:800px){.capacity-fields{grid-template-columns:1fr 1fr}.capacity-calendar{grid-template-columns:1fr}}
</style>
